'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readingLabels={'Not set':'Henüz belirtilmedi',Unread:'Okunacak',Reading:'Okunuyor',Read:'Okundu'},typeLabels={Fiction:'Roman / kurgu','Non-fiction':'Kurgu dışı',Poetry:'Şiir',Drama:'Tiyatro',Reference:'Başvuru',Other:'Diğer'};
const genreLabels={Literature:'Edebiyat',Physics:'Fizik',Astronomy:'Astronomi',Psychology:'Psikoloji',Biography:'Biyografi',Technology:'Teknoloji',Poetry:'Şiir',Languages:'Dil öğrenimi',Mystery:'Polisiye','History & politics':'Tarih ve siyaset','Religion & philosophy':'Din ve felsefe','Business & finance':'İş ve finans','Personal development':'Kişisel gelişim','Fantasy & science fiction':'Fantastik ve bilimkurgu'};
let catalogueEpoch=0;
let csvPreview=null,csvRunning=false,csvController=null,csvReading=0,transferModule;
let books=[],categories=[],editingId=null,detailId=null,selectedCover={},touched=new Set(),autoValues={},selection=false,selected=new Set(),visible=[],busy=false,deleteIds=[],lookupTimer,lookupGeneration=0,lookupResults=[],topicIds=null,layout='grid';
try{layout=localStorage.getItem('necle-layout')||'grid';}catch{}
const uiText=value=>window.SayfaI18n?.text(value)??value;
const normalize=s=>String(s||'').trim().toLocaleLowerCase().normalize('NFKD').replace(/\p{M}/gu,'').replace(/ı/g,'i').replace(/ə/g,'e'),today=()=>new Date().toISOString().slice(0,10),fileSize=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
const coverURL=url=>url?.startsWith('/api/')||url?.startsWith('/covers/')?url:'/api/cover-image?url='+encodeURIComponent(url||'');
function cover(book){return `<div class="cover ${esc(book.color||'forest')}"><span data-user-content>${esc(book.author||uiText('Kitaplığım'))}</span><strong data-user-content>${esc(book.title)}</strong><i aria-hidden="true">❦</i>${book.coverUrl?`<img src="${esc(coverURL(book.coverUrl))}" alt="${esc(book.title)} kapağı" loading="lazy">`:''}</div>`;}
function coverFields(book){return {coverUrl:book.coverUrl||'',coverSource:book.coverSource||book.sourceUrl||'',coverTitle:book.coverTitle||book.title||'',coverAuthor:book.coverAuthor||book.author||'',coverLanguage:book.coverLanguage||book.language||'',coverProvider:book.coverProvider||book.provider||'',coverNote:'Kapak ve baskı bilgileri farklı olabilir.'};}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5500);}
async function api(path,method='GET',data,signal){let response;try{response=await fetch('/api/'+path,{method,signal,headers:{...(method==='GET'?{}:{'Content-Type':'application/json'}),...await window.sayfaAuth?.headers?.()},...(data!==undefined?{body:JSON.stringify(data)}:{})});}catch(error){if(signal?.aborted)throw error;throw Error('Kütüphaneye ulaşılamıyor. Bağlantınızı kontrol edin.');}let result;try{result=await response.json();}catch{throw Error('Sunucudan beklenmeyen bir yanıt geldi.');}if(!response.ok){if(response.status===401)window.dispatchEvent(new Event('sayfa-needs-login'));throw Error(result.error||'İşlem tamamlanamadı.');}if(method!=='GET')catalogueEpoch++;return result;}
async function load(){const owner=currentUser?.id,epoch=catalogueEpoch;try{const data=await Promise.all([api('books'),api('categories')]);if(owner!==currentUser?.id||epoch!==catalogueEpoch)return;[books,categories]=data;$('connection-error').hidden=true;render();}catch(error){$('connection-error').textContent=error.message;$('connection-error').hidden=false;}}
function categoryNames(){return [...new Set([...categories.map(c=>c.name),...books.map(b=>b.genre)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,window.SayfaI18n?.locale||'tr'));}
function render(){
 $('total-count').textContent=books.length;$('physical-count').textContent=books.filter(b=>b.collection!=='digital').length;$('digital-count').textContent=books.filter(b=>b.collection==='digital').length;$('read-count').textContent=books.filter(b=>b.reading==='Read').length;
 const category=$('category-filter').value,names=categoryNames();$('category-filter').innerHTML='<option value="">Tüm kategoriler</option>'+names.map(name=>`<option data-user-content value="${esc(name)}" ${name===category?'selected':''}>${esc(name)}</option>`).join('');$('category-options').innerHTML=names.map(name=>`<option value="${esc(name)}"></option>`).join('');
 const query=normalize($('search').value),format=$('format-filter').value,state=$('reading-filter').value;
 let result=books.filter(b=>(format==='all'||(b.collection||'physical')===format)&&(!category||b.genre===category)&&(!state||(state==='loan'?!!b.borrower:b.reading===state))&&(topicIds?topicIds.includes(b.id):!query||[b.title,b.author,b.publisher,b.genre,b.isbn,b.notes,b.description,b.contentText].some(v=>normalize(v).includes(query))));
 const sort=$('sort').value;result.sort((a,b)=>topicIds?topicIds.indexOf(a.id)-topicIds.indexOf(b.id):sort==='title'?a.title.localeCompare(b.title,window.SayfaI18n?.locale||'tr'):sort==='author'?(a.author||'').localeCompare(b.author||'',window.SayfaI18n?.locale||'tr'):b.createdAt.localeCompare(a.createdAt));visible=result.map(b=>b.id);for(const id of selected)if(!books.some(b=>b.id===id))selected.delete(id);
 $('showing').textContent=`${books.length} kitaptan ${result.length} tanesi gösteriliyor`;$('clear-filters').hidden=!(query||format!=='all'||category||state||topicIds);$('select-books').hidden=selection||!books.length;$('bulk-actions').hidden=!selection;$('selection-count').textContent=`${selected.size} kitap seçildi`;
 for(const id of ['bulk-delete','bulk-read'])$(id).disabled=busy||!selected.size;$('cancel-selection').disabled=busy;$('select-visible').disabled=busy||!visible.length;$('select-visible').textContent=visible.length&&visible.every(id=>selected.has(id))?'Görünenlerin seçimini kaldır':'Görünenlerin tümünü seç';
 $('books').className='book-grid'+(layout==='list'?' list':'');$('layout-toggle').textContent=layout==='grid'?'Liste':'Kapaklar';
 $('books').innerHTML=result.length?result.map(book=>`<article class="book-card ${selected.has(book.id)?'selected':''}">${selection?`<label class="book-checkbox"><input type="checkbox" data-select="${esc(book.id)}" ${selected.has(book.id)?'checked':''} ${busy?'disabled':''} aria-label="${esc(book.title)} kitabını seç"><span>Seç</span></label>`:''}<button class="cover-button" data-book="${esc(book.id)}">${cover(book)}</button><div class="book-info"><span class="format-label">${book.collection==='digital'?'DİJİTAL':'FİZİKSEL'}</span><button class="book-title" data-user-content data-book="${esc(book.id)}">${esc(book.title)}</button><p class="author" data-user-content>${esc(book.author||'Yazar belirtilmedi')}</p><div class="tags"><span ${book.genre?'data-user-content':''}>${esc(book.genre||typeLabels[book.type]||'Kategorisiz')}</span><span>${book.borrower?'Ödünç verildi':readingLabels[book.reading]||''}</span></div></div></article>`).join(''):`<div class="empty-state"><span aria-hidden="true">❦</span><h3>${books.length?'Bu aramada kitap bulunamadı.':'Kitaplığınızın ilk sayfası.'}</h3><p>${books.length?'Farklı bir sözcük deneyin veya filtreleri temizleyin.':'İlk kitabınızı elle, kapak fotoğrafıyla veya dijital dosya olarak ekleyin. Tüm kitaplarınız burada bir arada görünecek.'}</p>${books.length?'<button class="secondary" data-empty="clear">Filtreleri temizle</button>':'<button class="primary" data-empty="add">İlk kitabımı ekle</button>'}</div>`;
}
function clearFilters(){topicIds=null;$('search').value='';$('format-filter').value='all';$('category-filter').value='';$('reading-filter').value='';$('topic-status').hidden=true;render();}
function finishSelection(){selection=false;selected.clear();render();}
function openBook(book){editingId=book?.id||null;touched=new Set();autoValues={};selectedCover=book?coverFields(book):{};renderSelectedCover();$('book-form').reset();$('form-title').textContent=book?'Kitap kaydını düzenle':'Yeni bir kitap';$('form-error').textContent='';$('lookup-results').innerHTML='';$('lookup-status').textContent=book?'Bilgileri dilediğiniz gibi düzenleyebilirsiniz.':'Kitabın adını yazın; bulunan bilgiler otomatik doldurulur.';if(book)for(const [key,value] of Object.entries(book)){const field=$('book-form').elements.namedItem(key);if(field&&typeof value==='string')field.value=value;}if(book)for(const name of ['author','publisher','genre','type','language','year','pages','isbn','description'])touched.add(name);$('book-form').elements.collection.disabled=!!book;$('loan-fields').hidden=book?.collection==='digital';if($('detail-dialog').open)$('detail-dialog').close();$('book-dialog').showModal();}
function showBook(id){const book=books.find(b=>b.id===id);if(!book)return;detailId=id;const info=[['Biçim',book.collection==='digital'?'Dijital':'Fiziksel'],['Kategori',book.genre],['Okuma durumu',readingLabels[book.reading]],['Yayınevi',book.publisher],['Yayın yılı',book.year],['Dil',book.language],['Sayfa sayısı',book.pages],['ISBN',book.isbn],['Raf',book.location]].filter(([,v])=>v);
 $('book-detail').innerHTML=`<div class="dialog-heading"><p class="eyebrow">KÜTÜPHANEMDEN</p><button class="close" data-detail="close" aria-label="Kapat">×</button></div><div class="dialog-body detail-layout">${cover(book)}<div><h2 data-user-content>${esc(book.title)}</h2><p class="detail-author" data-user-content>${esc(book.author||'Yazar belirtilmedi')}</p><dl>${info.map(([key,value])=>`<div><dt>${key}</dt><dd ${['Biçim','Okuma durumu'].includes(key)?'':'data-user-content'}>${esc(value)}</dd></div>`).join('')}</dl></div><section class="book-description"><h3>Kitap hakkında</h3><p data-user-content>${esc(book.descriptionKind==='Katalog bilgisi'?uiText('Açıklama eklenmedi.'):book.description||uiText('Açıklama eklenmedi.'))}</p>${book.notes?`<h3>Notlarım</h3><p data-user-content>${esc(book.notes)}</p>`:''}${book.borrower?`<p class="notice"><span data-user-content>${esc(book.borrower)}</span> <span>kişisine ödünç verildi.</span> ${book.dueDate?'<span>'+uiText('İade:')+'</span> '+esc(book.dueDate):''}</p>`:''}${book.files?.map(file=>`<div class="file-link"><span data-user-content>${esc(file.name)} · ${fileSize(file.size)}</span><a href="${esc(file.url)}" target="_blank" rel="noreferrer" class="secondary">${file.mime==='application/pdf'?'PDF’yi aç':'Dosyayı indir'}</a><a href="${esc(file.downloadUrl)}">İndir</a></div>`).join('')||''}${book.coverSource?`<p class="helper"><a href="${esc(book.coverSource)}" target="_blank" rel="noreferrer"><span>Kapak kaynağı:</span> ${esc(book.coverProvider||'Çevrimiçi katalog')}</a> · Baskı farklı olabilir.</p>`:''}</section></div><div class="dialog-footer"><button data-detail="delete" class="danger">Kitabı sil</button>${book.borrower?'<button data-detail="return" class="secondary">İade alındı</button>':''}<button data-detail="edit" class="primary">Düzenle</button></div>`;$('detail-dialog').showModal();}
function applySuggestion(book,explicit=false){if(!book)return;const form=$('book-form');if(explicit&&!editingId)form.elements.title.value=book.title;if(!editingId)for(const name of ['author','publisher','genre','type','language','year','pages','isbn','description']){let value=book[name];if(name==='genre')value=genreLabels[value]||value;if(value&&(!touched.has(name)||form.elements[name].value===autoValues[name])){form.elements[name].value=String(value);autoValues[name]=form.elements[name].value;}}if(book.coverUrl&&(explicit||!selectedCover.coverUrl))selectedCover=coverFields(book);renderSelectedCover();}
async function lookupBook(){clearTimeout(lookupTimer);const form=$('book-form'),title=form.elements.title.value.trim(),isbn=form.elements.isbn.value.trim();if(title.length<3&&!isbn)return;const generation=++lookupGeneration;$('lookup-status').textContent='Katalog bilgileri ve kapaklar aranıyor…';try{const result=await api('book-lookup?'+new URLSearchParams({title,isbn,author:touched.has('author')?form.elements.author.value:''}));if(generation!==lookupGeneration||!$('book-dialog').open)return;lookupResults=result.results||[];$('lookup-results').innerHTML=lookupResults.slice(0,8).map((b,i)=>`<button type="button" class="lookup-choice" data-choice="${i}">${b.coverUrl?`<img src="${esc(coverURL(b.coverUrl))}" alt="" loading="lazy">`:'<span>❦</span>'}<strong data-user-content>${esc(b.title)}</strong><small data-user-content>${esc(b.author)}${b.publisher?' · '+esc(b.publisher):''}</small></button>`).join('');if(result.recommendedIndex>=0&&!editingId)applySuggestion(lookupResults[result.recommendedIndex]);$('lookup-status').textContent=result.recommendedIndex>=0&&!editingId?'Bulunan bilgiler dolduruldu. Baskıyı kontrol edip kaydedebilirsiniz.':lookupResults.length?'Uygun baskıyı seçin. Bulunmayan alanları kendiniz doldurabilirsiniz.':'Güvenilir bir eşleşme bulunamadı. Elle ekleyebilirsiniz.';}catch(error){$('lookup-status').textContent=error.message;}}
async function ensureCategory(name){if(!name?.trim()||categories.some(c=>normalize(c.name)===normalize(name)))return;try{const created=await api('categories','POST',{name});categories=[...categories.filter(c=>c.id!==created.id),created];}catch{categories=await api('categories');}}
for(const button of document.querySelectorAll('[data-close]'))button.addEventListener('click',()=>$(button.dataset.close).close());
$('add-book').addEventListener('click',()=>openBook());$('add-photo').addEventListener('click',()=>{if(!photoRunning){for(const url of new Set(photoRows.map(row=>row.preview).filter(Boolean)))URL.revokeObjectURL(url);photoRows=[];$('photo-results').innerHTML='';$('photo-status').textContent='';$('photo-error').textContent='';renderPhotos();}$('photo-dialog').showModal();});$('add-files').addEventListener('click',()=>{if(!fileRunning){fileQueue=[];renderFiles();}$('file-dialog').showModal();});
for(const name of ['search','format-filter','category-filter','reading-filter','sort'])$(name).addEventListener(name==='search'?'input':'change',()=>{topicIds=null;$('topic-status').hidden=true;render();});$('clear-filters').addEventListener('click',clearFilters);$('layout-toggle').addEventListener('click',()=>{layout=layout==='grid'?'list':'grid';try{localStorage.setItem('necle-layout',layout);}catch{}render();});
$('books').addEventListener('click',event=>{const el=event.target.closest('[data-book],[data-empty]');if(!el)return;if(el.dataset.empty){el.dataset.empty==='add'?openBook():clearFilters();return;}if(selection){if(busy)return;selected.has(el.dataset.book)?selected.delete(el.dataset.book):selected.add(el.dataset.book);render();}else showBook(el.dataset.book);});$('books').addEventListener('change',event=>{const el=event.target.closest('[data-select]');if(!el||busy)return;el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render();});
$('select-books').addEventListener('click',()=>{selection=true;render();});$('cancel-selection').addEventListener('click',finishSelection);$('select-visible').addEventListener('click',()=>{const all=visible.every(id=>selected.has(id));for(const id of visible)all?selected.delete(id):selected.add(id);render();});
for(const name of ['author','publisher','genre','type','language','year','pages','isbn','description'])$('book-form').elements[name].addEventListener('input',()=>touched.add(name));$('book-form').elements.title.addEventListener('input',()=>{if(!editingId){for(const [name,value] of Object.entries(autoValues))if($('book-form').elements[name].value===value)$('book-form').elements[name].value=name==='type'?'Other':'';autoValues={};selectedCover={};renderSelectedCover();}lookupGeneration++;clearTimeout(lookupTimer);lookupTimer=setTimeout(lookupBook,1000);});$('lookup-book').addEventListener('click',lookupBook);$('lookup-results').addEventListener('click',event=>{const el=event.target.closest('[data-choice]');if(el){applySuggestion(lookupResults[Number(el.dataset.choice)],true);$('lookup-status').textContent='Bu baskının bilgileri seçildi.';}});$('book-dialog').addEventListener('close',()=>{clearTimeout(lookupTimer);lookupGeneration++;});
$('book-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,data={...Object.fromEntries(new FormData(form)),...selectedCover};if(editingId)data.collection=books.find(b=>b.id===editingId).collection;if(data.borrower&&!data.loanedAt)data.loanedAt=today();$('save-book').disabled=true;try{await ensureCategory(data.genre);const saved=await api(editingId?'books/'+editingId:'books',editingId?'PUT':'POST',data);books=editingId?books.map(b=>b.id===saved.id?saved:b):[saved,...books];$('book-dialog').close();render();toast('Kitap kaydedildi.');}catch(error){$('form-error').textContent=error.message;}finally{$('save-book').disabled=false;}});
$('book-detail').addEventListener('click',async event=>{const action=event.target.closest('[data-detail]')?.dataset.detail;if(!action)return;const book=books.find(b=>b.id===detailId);if(action==='close')$('detail-dialog').close();if(action==='edit')openBook(book);if(action==='delete')confirmDelete([detailId]);if(action==='return'){try{const saved=await api('books/'+detailId,'PUT',{...book,borrower:'',loanedAt:'',dueDate:''});books=books.map(b=>b.id===saved.id?saved:b);$('detail-dialog').close();render();toast('Kitap geri alındı.');}catch(error){toast(error.message);}}});
function confirmDelete(ids){deleteIds=ids.filter(id=>books.some(b=>b.id===id));if(!deleteIds.length)return;$('confirm-title').textContent=deleteIds.length===1?'Bu kitap silinsin mi?':`${deleteIds.length} kitap silinsin mi?`;$('confirm-copy').textContent='Bu işlem kitap kayıtlarını ve varsa yüklenen dijital dosyalarını kalıcı olarak siler.';$('delete-progress').textContent='';$('confirm-dialog').showModal();}
$('bulk-delete').addEventListener('click',()=>confirmDelete([...selected]));$('cancel-delete').addEventListener('click',()=>$('confirm-dialog').close());$('confirm-dialog').addEventListener('cancel',event=>{if(busy)event.preventDefault();});
$('confirm-delete').addEventListener('click',async()=>{if(busy)return;busy=true;$('confirm-delete').disabled=true;$('cancel-delete').disabled=true;let failed=0;try{for(const [i,id] of deleteIds.entries()){$('delete-progress').textContent=`${i+1} / ${deleteIds.length} siliniyor…`;try{await api('books/'+id,'DELETE',{});books=books.filter(b=>b.id!==id);}catch{failed++;}}$('confirm-dialog').close();if($('detail-dialog').open)$('detail-dialog').close();toast(failed?`${failed} kayıt silinemedi. Yeniden seçip deneyebilirsiniz.`:'Seçilen kitaplar silindi.');}finally{busy=false;$('confirm-delete').disabled=false;$('cancel-delete').disabled=false;finishSelection();}});
$('bulk-read').addEventListener('click',async()=>{if(busy)return;busy=true;render();let failed=0;try{for(const id of selected){const book=books.find(b=>b.id===id);try{const saved=await api('books/'+id,'PUT',{...book,reading:'Read'});books=books.map(b=>b.id===id?saved:b);}catch{failed++;}}toast(failed?`${failed} kayıt güncellenemedi.`:'Kitaplar okundu olarak işaretlendi.');}finally{busy=false;finishSelection();}});
function renderCategories(){$('category-list').innerHTML=categories.length?categories.map(c=>`<div class="category-row"><input data-category-name="${esc(c.id)}" aria-label="Kategori adı" value="${esc(c.name)}" maxlength="80"><button class="quiet" data-category-save="${esc(c.id)}">Güncelle</button><button class="quiet danger-text" data-category-delete="${esc(c.id)}">Sil</button></div>`).join(''):'<p class="helper">Henüz kategori yok. İlk kategorinizi yukarıdan oluşturun.</p>';}
$('manage-categories').addEventListener('click',()=>{renderCategories();$('category-error').textContent='';$('category-dialog').showModal();});$('category-form').addEventListener('submit',async event=>{event.preventDefault();try{const created=await api('categories','POST',{name:$('category-name').value});categories=[...categories.filter(c=>c.id!==created.id),created];$('category-name').value='';$('category-error').textContent='';renderCategories();render();}catch(error){$('category-error').textContent=error.message;}});$('category-list').addEventListener('click',async event=>{const save=event.target.closest('[data-category-save]'),remove=event.target.closest('[data-category-delete]'),id=save?.dataset.categorySave||remove?.dataset.categoryDelete;if(!id)return;const old=categories.find(c=>c.id===id),name=document.querySelector(`[data-category-name="${id}"]`).value;if(remove&&!window.confirm(uiText('Kategori silinsin mi? Kitaplar silinmez; yalnızca kategori etiketleri kaldırılır.')))return;try{await api('categories/'+id,save?'PUT':'DELETE',save?{name}:{});categories=save?categories.map(c=>c.id===id?{id,name}:c):categories.filter(c=>c.id!==id);books=books.map(b=>b.genre===old.name?{...b,genre:save?name:''}:b);renderCategories();render();}catch(error){$('category-error').textContent=error.message;}});

function cancelable(promise,signal){return new Promise((resolve,reject)=>{const abort=()=>reject(new DOMException('İşlem iptal edildi.','AbortError'));if(signal.aborted){abort();return;}signal.addEventListener('abort',abort,{once:true});Promise.resolve(promise).then(value=>{signal.removeEventListener('abort',abort);resolve(value);},error=>{signal.removeEventListener('abort',abort);reject(error);});});}
function jobBanner(message,kind){$('job-banner').hidden=false;$('job-banner').textContent=message;$('job-banner').dataset.kind=kind;}$('job-banner').addEventListener('click',()=>$($('job-banner').dataset.kind==='photo'?'photo-dialog':'file-dialog').showModal());
let fileQueue=[],fileRunning=false,fileController,metadataModule;
function renderFiles(){$('file-results').innerHTML=fileQueue.map(item=>`<article class="job-row ${item.status}"><strong data-user-content>${esc(item.file.name)}</strong><small>${fileSize(item.file.size)}</small><p>${esc(item.message||'Sırada bekliyor…')}</p>${item.status==='working'?'<progress max="100" value="'+(item.progress||0)+'"></progress>':''}</article>`).join('');const done=fileQueue.filter(item=>['saved','duplicate'].includes(item.status)).length;$('file-status').textContent=fileQueue.length?`${fileQueue.length} dosyadan ${done} tanesi kaydedildi.`:'';$('stop-files').hidden=!fileRunning;$('retry-files').hidden=fileRunning||!fileQueue.some(item=>['error','canceled'].includes(item.status));if(fileQueue.length)jobBanner(`${fileQueue.length} dosyadan ${done} tanesi kaydedildi. Ayrıntıları göster.`,'file');}
function uploadFile(item,metadata,signal){return new Promise((resolve,reject)=>{if(signal.aborted){reject(Error('İptal edildi.'));return;}const xhr=new XMLHttpRequest();xhr.open('POST','/api/digital-files');xhr.responseType='json';xhr.timeout=180000;const abort=()=>xhr.abort();signal.addEventListener('abort',abort,{once:true});xhr.onloadend=()=>signal.removeEventListener('abort',abort);xhr.upload.onprogress=event=>{if(event.lengthComputable){item.progress=Math.round(event.loaded/event.total*100);item.message='Yükleniyor… %'+item.progress;renderFiles();}};xhr.onabort=()=>reject(Error('İçe aktarma iptal edildi.'));xhr.onerror=()=>reject(Error('Bağlantı kesildi. Yeniden deneyebilirsiniz.'));xhr.ontimeout=()=>reject(Error('Yükleme zaman aşımına uğradı.'));xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve(xhr.response):reject(Error(xhr.response?.error||'Dosya yüklenemedi.'));const form=new FormData();form.append('file',item.file,item.file.name);form.append('metadata',JSON.stringify(metadata));if(item.thumbnail)form.append('thumbnail',item.thumbnail,'cover.jpg');xhr.send(form);});}
async function processFiles(){if(fileRunning)return;fileRunning=true;fileController=new AbortController();const signal=fileController.signal;renderFiles();try{for(const item of fileQueue){if(signal.aborted)break;if(item.status!=='pending')continue;try{if(!item.file.size||item.file.size>25*1024*1024)throw Error('Dosya boş olmamalı ve 25 MB’ı aşmamalıdır.');item.status='working';item.message='Dosyanın bilgileri okunuyor…';renderFiles();metadataModule||=import('/file-metadata.js');const parser=await metadataModule,details=await cancelable(parser.inspectFile(item.file,{signal}),signal);signal.throwIfAborted();item.thumbnail=details.coverBlob;const {coverBlob,...metadata}=details;metadata.collection='digital';metadata.reading='Not set';metadata.color='forest';if(details.reliableTitle){item.message='Katalog ve kapak aranıyor…';renderFiles();try{const result=await api('book-lookup?'+new URLSearchParams({title:details.title,author:details.author||'',isbn:details.isbn||''}),'GET',undefined,signal),candidate=result.results?.[result.recommendedIndex];if(candidate){for(const name of ['author','publisher','description','genre','type','language','year','pages','isbn'])if(candidate[name]&&(!metadata[name]||metadata[name]==='Other'))metadata[name]=candidate[name];Object.assign(metadata,coverFields(candidate));}}catch(error){if(signal.aborted)throw error;}}metadata.genre=genreLabels[metadata.genre]||metadata.genre;signal.throwIfAborted();item.message='Özel kitaplığınıza yükleniyor…';renderFiles();const result=await uploadFile(item,metadata,signal);if(!result?.book)throw Error('Yükleme yanıtı alınamadı.');catalogueEpoch++;await ensureCategory(result.book.genre);books=[result.book,...books.filter(b=>b.id!==result.book.id)];item.status=result.duplicate?'duplicate':'saved';item.message=result.duplicate?'Bu dosya zaten var; tekrar eklenmedi.':'Kaydedildi.';render();}catch(error){item.status=signal.aborted?'canceled':'error';item.message=signal.aborted?'İptal edildi. Sunucunun aldığı dosyalar kaydedilmiş olabilir.':error.message;}finally{item.thumbnail=null;}renderFiles();}}finally{fileRunning=false;renderFiles();if(signal.aborted)await load();}}
$('choose-files').addEventListener('click',()=>$('files-input').click());$('files-input').addEventListener('change',event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;if(!fileRunning)fileQueue=[];for(const file of files)fileQueue.push({file,status:'pending',progress:0});processFiles();});$('stop-files').addEventListener('click',()=>{for(const item of fileQueue)if(item.status==='pending'){item.status='canceled';item.message='İptal edildi.';}fileController?.abort();renderFiles();});$('retry-files').addEventListener('click',()=>{for(const item of fileQueue)if(['error','canceled'].includes(item.status))item.status='pending';processFiles();});
let photoRows=[],photoRunning=false,photoController,ocrModule;
function renderPhotos(){$('photo-results').innerHTML=photoRows.map((row,i)=>`<article class="photo-result ${row.saved?'saved':''}"><div class="photo-result-heading"><label><input type="checkbox" data-photo-select="${i}" ${row.selected?'checked':''} ${row.saved?'disabled':''}>${row.saved?'Kaydedildi':'Bu kitabı ekle'}</label>${row.coverUrl?`<img src="${esc(coverURL(row.coverUrl))}" alt="Bulunan kapak" loading="lazy">`:row.preview?`<img src="${esc(row.preview)}" alt="Kitap fotoğrafı">`:''}</div><p class="helper">${esc(row.message||'Baskı ve bilgileri kontrol edin.')}</p><div class="form-row"><label>Kitap adı<input data-photo-field="title" data-row="${i}" value="${esc(row.title)}" maxlength="200" ${row.saved?'disabled':''}></label><label>Yazar<input data-photo-field="author" data-row="${i}" value="${esc(row.author)}" maxlength="200" ${row.saved?'disabled':''}></label></div><div class="form-row"><label>Yayınevi<input data-photo-field="publisher" data-row="${i}" value="${esc(row.publisher)}" maxlength="200" ${row.saved?'disabled':''}></label><label>Kategori<input data-photo-field="genre" data-row="${i}" list="category-options" value="${esc(row.genre)}" maxlength="80" ${row.saved?'disabled':''}></label></div>${row.choices?.length?`<label>Başka bir baskı seçin<select data-photo-edition="${i}" ${row.saved?'disabled':''}><option value="">Mevcut bilgiler</option>${row.choices.slice(0,8).map((b,j)=>`<option data-user-content value="${j}">${esc(b.title)} — ${esc(b.author)}</option>`).join('')}</select></label>`:''}<details><summary>Okunan yazıyı göster</summary><p class="ocr-text">${esc(row.ocrText)}</p></details><p class="error">${esc(row.error||'')}</p></article>`).join('');$('save-photos').disabled=photoRunning||!photoRows.some(row=>row.selected&&!row.saved&&row.title?.trim());$('stop-photos').hidden=!photoRunning;}
async function photoCandidates(ocr,signal){
 const collected=[],queries=ocr.isbn.length?ocr.isbn.slice(0,6).map(isbn=>({isbn,title:''})):ocr.queries.slice(0,6).map(title=>({title}));
 for(let offset=0;offset<queries.length;offset+=2){await Promise.all(queries.slice(offset,offset+2).map(async params=>{try{const result=await api('book-lookup?'+new URLSearchParams(params),'GET',undefined,signal);collected.push(...result.results);}catch(error){if(signal.aborted)throw error;}}));signal.throwIfAborted();}
 const parser=await ocrModule;return parser.matchPhotoBooks(ocr.text,collected).map(item=>ocr.isbn.includes(String(item.book.isbn||'').replace(/[\s-]/g,''))?{...item,score:3}:item).sort((a,b)=>b.score-a.score);
}
async function processPhotos(files){if(photoRunning)return;photoRunning=true;photoController=new AbortController();const signal=photoController.signal;renderPhotos();try{ocrModule||=import('/ocr-reader.js');const parser=await ocrModule;for(const [index,file]of files.entries()){signal.throwIfAborted();$('photo-status').textContent=`${index+1} / ${files.length}: ${file.name} okunuyor…`;jobBanner($('photo-status').textContent,'photo');try{const ocr=await cancelable(parser.recognizePhoto(file,(progress,message)=>{if(!signal.aborted)$('photo-status').textContent=`${index+1} / ${files.length}: ${message}${progress?' %'+progress:''}`;},signal),signal);signal.throwIfAborted();$('photo-status').textContent='Algılanan kitaplar kataloglarda aranıyor…';const ranked=await photoCandidates(ocr,signal);const strong=ranked.filter(r=>r.score>=.85&&(r.words>=2||r.score>=2)).slice(0,8),chosen=strong.length?strong:ranked.slice(0,1);const preview=ocr.thumbnail?URL.createObjectURL(ocr.thumbnail):'';if(!chosen.length)chosen.push({book:{title:ocr.queries[1]||ocr.queries[0]||'',author:'',publisher:'',type:'Other'},score:0});for(const candidate of chosen){const b=candidate.book;if(photoRows.some(row=>normalize(row.title+' '+row.author)===normalize(b.title+' '+b.author)))continue;const existing=books.some(old=>normalize(old.title+' '+old.author)===normalize(b.title+' '+b.author));photoRows.push({...b,genre:genreLabels[b.genre]||b.genre||'',thumbnail:ocr.thumbnail,preview,ocrText:ocr.text,choices:ranked.map(r=>r.book),selected:!!b.title&&!existing,saved:false,message:existing?'Bu kitap zaten kitaplığınızda. İkinci bir kopyayı isterseniz seçebilirsiniz.':candidate.score>=.85?'Yazıyla güçlü bir eşleşme bulundu. Baskı bilgilerini kontrol edin.':'Eşleşme kesin değil. Adı, yazarı ve baskıyı kontrol edin.'});}renderPhotos();}catch(error){if(signal.aborted)throw error;$('photo-error').textContent=file.name+': '+error.message;}}$('photo-status').textContent=`${photoRows.length} kitap adayı hazır. Bilgileri kontrol ederek seçilenleri ekleyin.`;}catch(error){$('photo-status').textContent=signal.aborted?'Fotoğraf okuma durduruldu. Hazır kayıtları yine de ekleyebilirsiniz.':error.message;}finally{photoRunning=false;renderPhotos();jobBanner($('photo-status').textContent,'photo');}}
$('take-photo').addEventListener('click',()=>$('camera-input').click());$('choose-photos').addEventListener('click',()=>$('photos-input').click());for(const id of ['camera-input','photos-input'])$(id).addEventListener('change',event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;if(photoRunning){toast('Önce devam eden okumayı durdurun.');return;}$('photo-error').textContent='';processPhotos(files);});$('stop-photos').addEventListener('click',()=>photoController?.abort());
$('photo-results').addEventListener('input',event=>{const el=event.target;if(el.dataset.photoField){photoRows[Number(el.dataset.row)][el.dataset.photoField]=el.value;$('save-photos').disabled=photoRunning||!photoRows.some(row=>row.selected&&!row.saved&&row.title?.trim());}if(el.dataset.photoSelect!==undefined){photoRows[Number(el.dataset.photoSelect)].selected=el.checked;$('save-photos').disabled=photoRunning||!photoRows.some(row=>row.selected&&!row.saved&&row.title?.trim());}});$('photo-results').addEventListener('change',event=>{const el=event.target;if(el.dataset.photoEdition!==undefined&&el.value!==''){const row=photoRows[Number(el.dataset.photoEdition)],candidate=row.choices[Number(el.value)];Object.assign(row,candidate,{genre:genreLabels[candidate.genre]||candidate.genre||''});renderPhotos();}});
$('save-photos').addEventListener('click',async()=>{if(photoRunning)return;photoRunning=true;photoController=new AbortController();const signal=photoController.signal;renderPhotos();let savedCount=0;try{for(const row of photoRows){if(signal.aborted)break;if(!row.selected||row.saved||!row.title?.trim())continue;try{const form=new FormData();const {thumbnail,preview,choices,ocrText,selected,saved,message,error,...fields}=row;form.append('metadata',JSON.stringify({...fields,...coverFields(row),reading:'Not set',type:row.type||'Other',collection:'physical'}));if(thumbnail)form.append('photo',thumbnail,'cover.jpg');const response=await fetch('/api/photo-books',{method:'POST',body:form,signal});const result=await response.json();if(!response.ok)throw Error(result.error||'Kitap eklenemedi.');catalogueEpoch++;await ensureCategory(result.genre);books.unshift(result);row.saved=true;row.selected=false;row.error='';savedCount++;}catch(error){row.error=signal.aborted?'Kaydetme durduruldu. Sunucuya ulaşan kayıtlar kaydedilmiş olabilir.':error.message;if(signal.aborted)break;}renderPhotos();render();}toast(`${savedCount} kitap kütüphanenize eklendi.`);}finally{photoRunning=false;renderPhotos();if(signal.aborted){$('photo-status').textContent='Kaydetme durduruldu. Kaydedilmiş kitaplar korunur.';await load();}}});
document.addEventListener('error',event=>{if(event.target.matches?.('.cover img'))event.target.remove();},true);window.addEventListener('beforeunload',event=>{if(fileRunning||photoRunning||csvRunning){event.preventDefault();event.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(currentUser&&!document.hidden&&!fileRunning&&!photoRunning&&!document.querySelector('dialog[open]'))load();});

function renderSelectedCover(){$('selected-cover').hidden=!selectedCover.coverUrl;$('selected-cover').innerHTML=selectedCover.coverUrl?`<img src="${esc(coverURL(selectedCover.coverUrl))}" alt="Seçilen kapak"><span>Seçilen kitap kapağı</span><button type="button" class="quiet" id="remove-cover">Kapağı kaldır</button>`:'';}
