$('book-form').elements.collection.addEventListener('change',()=>{$('loan-fields').hidden=$('book-form').elements.collection.value==='digital';if($('loan-fields').hidden)for(const name of ['borrower','loanedAt','dueDate'])$('book-form').elements[name].value='';});

let currentUser=null,currentView='home',sessionGeneration=0,pendingView=null;
const routePaths={home:'/',login:'/login',register:'/register',library:'/library',guide:'/guide',account:'/account',admin:'/admin',privacy:'/privacy'};
function navigate(view,{replace=false}={}){
 if(['login','register'].includes(view)&&currentUser)view='library';if(['library','guide','account','admin'].includes(view)&&!currentUser){pendingView=view;view='login';}if(view==='admin'&&!currentUser?.isAdmin)view='account';
 currentView=view;const authView=['login','register'].includes(view);document.body.dataset.authView=view;document.body.dataset.view=view;
 for(const element of document.querySelectorAll('.view[data-view]'))element.hidden=element.dataset.view!==(authView?'auth':view);
 for(const element of document.querySelectorAll('[data-route]')){const active=element.dataset.route===view;element.classList.toggle('active',active);if(active)element.setAttribute('aria-current','page');else element.removeAttribute('aria-current');}
 if(authView){$('auth-heading').innerHTML=view==='register'?'Kendi kitaplığına<br><em>ilk sayfayı aç.</em>':'Yeniden<br><em>hoş geldin.</em>';$('auth-description').textContent=view==='register'?'Kitaplarına, dosyalarına ve notlarına sana özel bir yer.':'Kitapların kaldığın yerde seni bekliyor.';$('auth-card-label').textContent=view==='register'?'KAYIT OL':'GİRİŞ YAP';$('auth-card-title').textContent=view==='register'?'Okuma alanını oluştur.':'Kitaplığına dön.';$('auth-submit').textContent=view==='register'?'Hesap oluştur':'Giriş yap';$('auth-password').autocomplete=view==='register'?'new-password':'current-password';$('auth-password').minLength=view==='register'?12:1;$('name-field').hidden=view!=='register';$('forgot-password').hidden=view==='register';$('auth-switch').innerHTML=view==='register'?'Zaten hesabın var mı? <button class="inline-link" data-route="login">Giriş yap</button>':'İlk kez mi geliyorsun? <button class="inline-link" data-route="register">Hesap oluştur</button>';$('auth-error').textContent='';}
 if(routePaths[view]&&location.pathname!==routePaths[view]){if(replace)history.replaceState(null,'',routePaths[view]);else history.pushState(null,'',routePaths[view]);}
 if(view==='account')loadAccount();if(view==='admin')loadAdministration();window.scrollTo?.({top:0,behavior:'instant'});
}
document.addEventListener('click',event=>{const route=event.target.closest('[data-route]');if(!route)return;event.preventDefault();navigate(route.dataset.route);});
window.addEventListener('popstate',()=>navigate(Object.keys(routePaths).find(key=>routePaths[key]===location.pathname)||'home',{replace:true}));
function clearPrivateState(){csvController?.abort();csvReading++;csvPreview=null;$('csv-preview').hidden=true;$('csv-input').value='';$('csv-sample').innerHTML='';$('csv-errors').innerHTML='';$('csv-filename').textContent='';$('csv-export-status').textContent='';for(const id of ['csv-progress','csv-summary','csv-warning'])$(id).textContent='';fileController?.abort();photoController?.abort();books=[];categories=[];selected.clear();selection=false;topicIds=null;for(const url of new Set(photoRows.map(row=>row.preview).filter(Boolean)))URL.revokeObjectURL(url);photoRows=[];fileQueue=[];for(const dialog of document.querySelectorAll('dialog[open]:not(#language-dialog)'))dialog.close();$('book-detail').innerHTML='';$('photo-results').innerHTML='';$('file-results').innerHTML='';$('guide-results').innerHTML='';$('admin-users').innerHTML='';$('book-form').reset();$('search').value='';$('guide-query').value='';$('profile-name').value='';$('profile-email').value='';$('job-banner').hidden=true;render();}
async function refreshSession(){const generation=++sessionGeneration;try{let session=await api('session');if(generation!==sessionGeneration)return;if(session.authenticated&&!session.registered){await api('account/create','POST',{displayName:(session.identity?.name||session.identity?.email?.split('@')[0]||'Okur').slice(0,100)});session=await api('session');}if(generation!==sessionGeneration)return;const user=session.user;if(currentUser?.id!==user?.id)clearPrivateState();currentUser=user||null;$('guest-actions').hidden=!!user;$('member-actions').hidden=!user;$('home-library-link').hidden=!user;$('admin-link').hidden=!user?.isAdmin;$('header-name').textContent=user?.displayName||'Hesabım';document.body.dataset.signedIn=user?'true':'false';if(user){await load();if(generation!==sessionGeneration)return;if(pendingView){const target=pendingView;pendingView=null;navigate(target,{replace:true});}else if(['login','register','verification'].includes(currentView)||location.pathname==='/auth/complete'||location.pathname==='/library')navigate('library',{replace:true});resumeAdding();}else if(['library','guide','account','admin','verification'].includes(currentView))navigate('login',{replace:true});
 }catch(error){$('connection-error').textContent=error.message;$('connection-error').hidden=false;}}
window.addEventListener('sayfa-auth-changed',refreshSession);window.addEventListener('sayfa-needs-login',()=>{sessionGeneration++;if(currentUser)clearPrivateState();currentUser=null;$('guest-actions').hidden=false;$('member-actions').hidden=true;navigate('login',{replace:true});});
window.addEventListener('sayfa-verification',event=>{if(currentUser)clearPrivateState();currentUser=null;$('verification-email').textContent=event.detail.email||'';navigate('verification');});
$('guide-form').addEventListener('submit',async event=>{event.preventDefault();const query=$('guide-query').value.trim();if(query.length<3)return;$('topic-search').disabled=true;$('guide-results').textContent='Kitaplığının sayfaları arasında aranıyor…';try{const result=await api('library-assistant','POST',{query,collection:$('guide-format').value});$('guide-results').innerHTML=(result.matches.length?'<p class="helper">'+esc(result.answer)+'</p>':'<div class="guide-empty">Henüz uygun bir eşleşme bulunamadı. Bir konu, yazar veya hatırladığın birkaç sözcükle yeniden dene.</div>')+result.matches.map(match=>{const book=books.find(b=>b.id===match.id);return book?`<article class="guide-match"><button data-guide-book="${esc(book.id)}" class="guide-cover">${cover(book)}</button><div><span class="eyebrow">${book.collection==='digital'?'DİJİTAL':'FİZİKSEL'}</span><button data-guide-book="${esc(book.id)}" class="guide-title" data-user-content>${esc(book.title)}</button><p data-user-content>${esc(book.author)}</p><p data-user-content>${esc(match.reason)}</p></div></article>`:'';}).join('');}catch(error){$('guide-results').textContent=error.message;}finally{$('topic-search').disabled=false;}});
$('guide-results').addEventListener('click',event=>{const button=event.target.closest('[data-guide-book]');if(button)showBook(button.dataset.guideBook);});
for(const button of document.querySelectorAll('[data-guide-query]'))button.addEventListener('click',()=>{$('guide-query').value=uiText(button.dataset.guideQuery);$('guide-query').focus();});
async function loadAccount(){const owner=currentUser?.id;try{const account=await api('account');if(owner!==currentUser?.id)return;$('profile-name').value=account.user.displayName;$('profile-email').value=account.user.email;$('usage-number').textContent=(account.storageBytes/1048576).toFixed(1)+' MB';$('usage-copy').textContent=`${account.books} / ${account.limits.bookLimit} kitap · ${(account.limits.storageBytes/1048576).toFixed(0)} MB dosya alanı`;$('usage-progress').value=Math.min(100,account.storageBytes/account.limits.storageBytes*100);}catch(error){toast(error.message);}}
$('profile-form').addEventListener('submit',async event=>{event.preventDefault();try{const user=await api('account','PATCH',{displayName:$('profile-name').value});currentUser=user;$('header-name').textContent=user.displayName;$('profile-message').textContent='Adın güncellendi.';}catch(error){$('profile-message').textContent=error.message;}});

function downloadData(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('export-csv').addEventListener('click',async()=>{const owner=currentUser?.id;$('export-csv').disabled=true;$('csv-export-status').textContent='CSV hazırlanıyor…';try{const response=await fetch('/api/account/export.csv',{headers:await window.sayfaAuth?.headers?.()});if(!response.ok)throw Error((await response.json()).error||'İşlem tamamlanamadı.');const blob=await response.blob();if(owner!==currentUser?.id)return;downloadData(blob,'sayfa-library-'+today()+'.csv');$('csv-export-status').textContent='CSV indirildi. Bu dosya özel notlarını ve ödünç bilgilerini de içerir.';}catch(error){if(owner===currentUser?.id)$('csv-export-status').textContent=error.message;}finally{$('export-csv').disabled=false;}});
$('csv-template').addEventListener('click',async()=>{try{transferModule||=import('/library-transfer.js');const {CSV_TEMPLATE}=await transferModule;downloadData(new Blob([CSV_TEMPLATE],{type:'text/csv;charset=utf-8'}),'sayfa-example.csv');}catch(error){toast(error.message);}});
$('choose-csv').addEventListener('click',()=>$('csv-input').click());
function renderCSVPreview(){if(!csvPreview)return;const p=csvPreview;$('csv-preview').hidden=false;$('csv-summary').textContent=`${p.books.length} kitap · ${p.categories.length} kategori · ${p.errors.length} hatalı satır`;$('csv-warning').textContent=(p.attachments?'CSV orijinal belge dosyalarını içermez. Dosyalar ayrıca taşınmalıdır. ':'')+(p.missingCovers?'Özel veya desteklenmeyen kapak bağlantıları aktarılmadı. ':'');$('csv-errors').innerHTML=p.errors.slice(0,8).map(e=>`<li>${esc(uiText('Satır'))} ${e.line}: ${esc(uiText(e.error))}</li>`).join('');$('csv-sample').innerHTML=p.books.slice(0,5).map(b=>`<div><strong data-user-content>${esc(b.title)}</strong><span data-user-content>${esc(b.author)}</span><small>${b.collection==='digital'?'Dijital':'Fiziksel'}</small></div>`).join('');$('import-csv').disabled=csvRunning||p.errors.length>0||(!p.books.length&&!p.categories.length);}
$('csv-input').addEventListener('change',async event=>{const file=event.target.files?.[0];event.target.value='';if(!file||csvRunning)return;const generation=++csvReading,owner=currentUser?.id;csvPreview=null;$('csv-preview').hidden=false;$('csv-filename').textContent=file.name;$('csv-summary').textContent='CSV okunuyor…';$('csv-warning').textContent='';$('csv-errors').innerHTML='';$('csv-sample').innerHTML='';$('csv-progress').textContent='';$('import-csv').disabled=true;try{if(file.size>20*1024*1024)throw Error('CSV dosyası en fazla 20 MB olabilir.');transferModule||=import('/library-transfer.js');const {parseLibraryCSV}=await transferModule,text=await file.text();if(generation!==csvReading||owner!==currentUser?.id)return;csvPreview=parseLibraryCSV(text);renderCSVPreview();}catch(error){if(generation===csvReading&&owner===currentUser?.id)$('csv-summary').textContent=uiText(error.message);}});
$('cancel-csv').addEventListener('click',()=>{if(csvRunning){csvController?.abort();return;}csvReading++;csvPreview=null;$('csv-preview').hidden=true;$('csv-filename').textContent='';$('csv-sample').innerHTML='';$('csv-errors').innerHTML='';});
$('import-csv').addEventListener('click',async()=>{if(csvRunning||!csvPreview||csvPreview.errors.length)return;const preview=csvPreview,owner=currentUser?.id;csvRunning=true;csvController=new AbortController();const signal=csvController.signal;let added=0,skipped=0,position=0,categoriesSent=false,completed=false;$('choose-csv').disabled=true;$('import-csv').disabled=true;$('cancel-csv').textContent='İçe aktarmayı durdur';try{
 while(position<preview.books.length||!categoriesSent){signal.throwIfAborted();const batch=[];let size=JSON.stringify(preview.categories).length;while(position<preview.books.length&&batch.length<20){const record={...preview.books[position]};delete record.csvLine;const length=JSON.stringify(record).length;if(batch.length&&size+length>1400000)break;batch.push(record);size+=length;position++;}
 const result=await api('account/import-csv','POST',{books:batch,categories:categoriesSent?[]:preview.categories},signal);categoriesSent=true;if(owner!==currentUser?.id)return;added+=result.added;skipped+=result.skipped;$('csv-progress').textContent=`${position} / ${preview.books.length} işlendi · ${added} eklendi · ${skipped} atlandı`;if(result.limited.length)throw Error('Kitap sınırına ulaşıldı. Kaydedilenler korunur; CSV dosyasını yeniden yükleyerek devam edebilirsiniz.');
 }completed=true;$('csv-progress').textContent=`İçe aktarma tamamlandı: ${added} kitap eklendi, ${skipped} kitap atlandı.`;
 }catch(error){if(owner===currentUser?.id)$('csv-progress').textContent=signal.aborted?'İçe aktarma durduruldu. Sunucuya ulaşan kayıtlar kaydedilmiş olabilir. Aynı CSV ile güvenle devam edebilirsiniz.':uiText(error.message);}
 finally{csvRunning=false;$('choose-csv').disabled=false;$('cancel-csv').textContent='Vazgeç';if(owner===currentUser?.id){await load();await loadAccount();$('import-csv').disabled=completed;if(completed){csvPreview=null;$('csv-sample').innerHTML='';}}}
});
$('export-account').addEventListener('click',async()=>{try{const data=await api('account/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='sayfa-kitapligim-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}});
$('erase-library').addEventListener('click',async()=>{if(!window.confirm(uiText('Tüm kitapların, kategorilerin ve yüklenen dosyaların kalıcı olarak silinsin mi? Bu işlem geri alınamaz.')))return;try{await api('account/library','DELETE',{});await load();await loadAccount();toast('Kitaplığın silindi.');}catch(error){toast(error.message);}});
async function loadAdministration(){if(!currentUser?.isAdmin)return;try{const owner=currentUser.id;const data=await api('admin/users');if(owner!==currentUser?.id||!currentUser?.isAdmin)return;$('admin-message').textContent=`${data.users.length} hesap · ${data.notice}`;$('admin-users').innerHTML='<div class="admin-row admin-labels"><span>Hesap</span><span>Kayıt tarihi</span><span>Kitap / dosya</span><span>Dosya alanı</span></div>'+data.users.map(user=>`<div class="admin-row"><span><strong data-user-content>${esc(user.display_name)}</strong><small data-user-content>${esc(user.email||'E-posta paylaşılmadı')}</small></span><span>${esc(new Date(user.created_at).toLocaleDateString(window.SayfaI18n?.locale||'tr-TR'))}</span><span>${user.book_count} / ${user.file_count}</span><span>${fileSize(user.file_bytes||0)}</span></div>`).join('');}catch(error){$('admin-message').textContent=error.message;}}

function startAdding(kind){
 if(!['photo','files','manual'].includes(kind))return;
 if(!currentUser){try{sessionStorage.setItem('sayfa-start',kind);}catch{}navigate('register');return;}
 navigate('library');$(kind==='photo'?'add-photo':kind==='files'?'add-files':'add-book').click();
}
function resumeAdding(){let kind;try{kind=sessionStorage.getItem('sayfa-start');sessionStorage.removeItem('sayfa-start');}catch{}if(kind)startAdding(kind);}
document.addEventListener('click',event=>{const button=event.target.closest('[data-start]');if(button)startAdding(button.dataset.start);});
const filterMedia=window.matchMedia?.('(min-width: 900px)');
if(filterMedia){const resizeFilters=()=>{$('library-filters').open=filterMedia.matches;};resizeFilters();filterMedia.addEventListener?.('change',resizeFilters);}

navigate(Object.keys(routePaths).find(key=>routePaths[key]===location.pathname)||'home',{replace:true});refreshSession();

window.addEventListener('sayfa-language-changed',()=>{render();if(currentView==='account'){loadAccount();renderCSVPreview();}if(currentView==='admin')loadAdministration();});
